defined('ABSPATH') || exit;
$has_current_consent = $preference && $preference->choice === 'portal' && $preference->version === BPM_Domain::CONSENT_VERSION;
$has_current_authority = $has_current_consent && (int)$preference->authority_confirmed === 1;
?>
  <section class="bpm-card <?= $needs_communication ? 'bpm-communication-prompt' : '' ?>" id="bpm-preference" aria-labelledby="bpm-communication-title"><h3 id="bpm-communication-title"><?= $needs_communication ? 'Bitte entscheiden Sie über die elektronische Zustellung' : 'Digitale Kommunikation' ?></h3><p>Ihre Mietpartei kann ausdrücklich die ausschließlich elektronische Übermittlung der in der Vereinbarung genannten Unterlagen wählen. Die Nutzung des Portals setzt keine Zustimmung zur digitalen Zustellung voraus.</p>
    <p><strong>Aktuelle Wahl:</strong> <?= esc_html($preference && $preference->choice === 'portal' ? 'Elektronische Zustellung vereinbart' : 'Keine aktive Vereinbarung zur digitalen Zustellung') ?><?php if ($preference): ?> · <?= esc_html(get_date_from_gmt($preference->created_at, 'd.m.Y H:i') . ' · Fassung ' . $preference->version) ?><?php endif; ?></p>
    <?php if (get_option('bpm_consent_enabled')): ?>
      <details <?= $needs_communication ? 'open' : '' ?>><summary>Vereinbarung lesen</summary><p><?= esc_html(BPM_Domain::CONSENT_TEXT) ?></p><p class="bpm-small">Textfassung <?= esc_html(BPM_Domain::CONSENT_VERSION) ?></p></details>
      <form method="post" action="<?= esc_url($endpoint) ?>"><?php BPM_Portal::form('preference'); ?><input type="hidden" name="choice" value="portal"><label class="bpm-check"><input name="agree" type="checkbox" value="1" <?= checked((bool)$has_current_consent, true, false) ?> required> Ich stimme der Vereinbarung ausdrücklich zu: Für die erfassten Unterlagen genügt die elektronische Übermittlung; zusätzliche Papierbriefe entfallen.</label><label class="bpm-check"><input name="authority" type="checkbox" value="1" <?= checked((bool)$has_current_authority, true, false) ?> required> Ich bin berechtigt, diese Wahl für die Mietpartei zu erklären, und habe sie mit den weiteren Vertragspartnern abgestimmt.</label><button type="submit">Wahl dokumentieren</button></form>
    <?php else: ?><p class="bpm-empty">Die Vereinbarung zur digitalen Zustellung wird noch vorbereitet. Bis zur Freigabe gelten Ihre bisherigen Kommunikationswege weiter.</p><?php endif; ?>
    <?php if ($preference && $preference->choice === 'portal'): ?><form method="post" action="<?= esc_url($endpoint) ?>"><?php BPM_Portal::form('preference'); ?><input type="hidden" name="choice" value="widerrufen"><button type="submit" class="bpm-secondary">Digitale Zustellung für die Zukunft widerrufen</button></form><?php endif; ?>
    <p class="bpm-small">Die Erklärung gilt für den gemeinsamen Zugang Ihrer Mietpartei. Sie ersetzt keine gesetzlich vorgeschriebene Form und bestätigt nicht automatisch den Zugang einzelner Schreiben.</p>
